 const vendorName=(id:string)=>vendors.find(v=>v.vendorId===id)?.name||"—",latest=useMemo(()=>{const result=new Map<string,Assessment>();for(const assessment of assessments)if((result.get(assessment.vendorId)?.cycleNumber||0)<assessment.cycleNumber)result.set(assessment.vendorId,assessment);return result},[assessments]);
