 function assessmentAction(a:Assessment,operation:string,riskAcceptanceReason=""){setNotice("");const p=profiles.find(v=>v.vendorId===a.vendorId);setActionForm({kind:"assessment",id:a.id,operation,riskAcceptanceReason,note:"",evidenceId:"",versionId:"",expectedRevision:a.updatedAt,confirmation:"",...(["approve","conditional"].includes(operation)?{reviewSchedule:{profileRevision:p?.updatedAt||"",previousDate:p?.nextReview||"",contractEnd:p?.contractEnd||"",nextDate:validNextReview(p?.nextReview,p?.contractEnd)?p!.nextReview!:""}}:{})})}
