  {tab==="overview"&&<div className="tprm-grid"><section><header><div><small>{tr?"RİSK ÖNCELİĞİ":"RISK PRIORITY"}</small><h3>{tr?"Müdahale bekleyen tedarikçiler":"Third parties requiring action"}</h3></div><span>{priorityVendors.length}</span></header>{!priorityVendors.length&&<div className="tprm-empty"><b>{profiles.length?(tr?"Öncelikli müdahale bekleyen tedarikçi yok":"No third parties need priority action"):(tr?"Henüz değerlendirilmiş tedarikçi yok":"No third parties assessed yet")}</b><p>{profiles.length?(tr?"İnceleme ve risk sinyalleri bu kuyrukta görünür.":"Review and risk signals appear in this queue."):(tr?"Bekleyen bir tedarikçiyi seçip değerlendirmeye başlayın.":"Adopt records into TPRM to begin their assessment.")}</p><button type="button" onClick={()=>setTab("vendors")}>{tr?"Tedarikçi envanterini aç":"Open third-party inventory"}</button></div>}{priorityVendors.slice(0,12).map(v=><VendorCard key={v.vendorId} vendor={v} assessment={latest.get(v.vendorId)} tr={tr} format={format} open={()=>setSelected(v)}/>)}</section><section><header><div><small>{tr?"ONBOARDING":"ONBOARDING"}</small><h3>{tr?"Onboarding bekleyen kayıtlar":"Awaiting onboarding"}</h3></div><span>{summary.unmanaged}</span></header>{!unmanagedVendors.length&&<div className="tprm-empty"><b>{tr?"Onboarding bekleyen kayıt yok":"No records awaiting onboarding"}</b><p>{tr?"Yeni tedarikçiler burada görünür.":"New suppliers appear here."}</p></div>}{unmanagedVendors.slice(0,10).map(v=><article className="tprm-unmanaged" key={v.vendorId}><div><b>{v.name}</b><small>{v.service} · {vendorCode(v.code,v.vendorId)}</small></div>{canWrite&&<button onClick={()=>startVendor(v)}>{tr?"Kapsama al":"Adopt"}</button>}</article>)}</section></div>}
